    Bug 1920131 - Implement EWS feature to mark message as read/unread when the status has changed on the EWS server. r=babolivier

    Differential Revision: https://phabricator.services.mozilla.com/D240971

diff --git a/mailnews/protocols/ews/src/EwsFolder.cpp b/mailnews/protocols/ews/src/EwsFolder.cpp
index 61d3e26eda9..7ea45b74978 100644
--- a/mailnews/protocols/ews/src/EwsFolder.cpp
+++ b/mailnews/protocols/ews/src/EwsFolder.cpp
@@ -230,6 +230,17 @@ NS_IMETHODIMP MessageOperationCallbacks::MaybeDeleteMessageFromStore(
   return hdr->AndFlags(~nsMsgMessageFlags::Offline, &unused);
 }

+NS_IMETHODIMP MessageOperationCallbacks::UpdateReadStatus(
+    const nsACString& ewsId, bool is_read) {
+  // Get the header for the message with ewsId and update its read flag in the
+  // database.
+  RefPtr<nsIMsgDBHdr> existingHeader;
+  rv = GetHeaderForItem(ewsId, getter_AddRefs(existingHeader));
+  NS_ENSURE_SUCCESS(rv, rv);
+
+  return existingHeader->MarkRead(is_read);
+}
+
 NS_IMETHODIMP MessageOperationCallbacks::UpdateSyncState(
     const nsACString& syncStateToken) {
   return mFolder->SetStringProperty(SYNC_STATE_PROPERTY, syncStateToken);
diff --git a/mailnews/protocols/ews/src/IEwsClient.idl b/mailnews/protocols/ews/src/IEwsClient.idl
index 0023c9a313c..0da4bc657e8 100644
--- a/mailnews/protocols/ews/src/IEwsClient.idl
+++ b/mailnews/protocols/ews/src/IEwsClient.idl
@@ -215,6 +215,18 @@ interface IEwsMessageCallbacks : nsISupports
    */
   void updateSyncState(in AUTF8String syncStateToken);

+  /**
+   * Update the read flag for the message with the given EWS ID.
+
+   * When a message is marked as read/unread on the EWS server, the EWS server
+   * will represent this either as an `Update` element or `ReadFlagChange`
+   * element when syncing the message list.
+   *
+   * If a `ReadFlagChange` element is returned, then this method updates the
+   * read/unread status of the existing message in the current folder's database.
+   */
+  void updateReadStatus(in AUTF8String ewsId, in boolean readStatus);
+
   /**
    * Signals that an error has happened during the current operation.
    *
diff --git a/rust/ews_xpcom/src/client.rs b/rust/ews_xpcom/src/client.rs
